INSERT INTO BuildingModifiers (BuildingType, ModifierId) SELECT 'BUILDING_BS_DECK_3_5_AXIS' || substr(BuildingType, 21), ModifierId FROM BuildingModifiers WHERE BuildingType = 'BUILDING_BS_DECK_3_5' OR BuildingType GLOB 'BUILDING_BS_DECK_3_5_S[0-9]*';
